void SourceReference::set_gmail(const ::context_hub::GmailReference& gmail) {
  if (tag_ == Tag::kGmail) {
    data_.gmail = std::move(gmail);
  } else {
    DestroyActive();
    tag_ = Tag::kGmail;
    new (&data_.gmail) ::context_hub::GmailReference(
        std::move(gmail));
  }
}

