bool UnionTraits<::browser::context_hub::mojom::SourceReference::DataView, ::browser::context_hub::mojom::SourceReferencePtr>::Read(
    ::browser::context_hub::mojom::SourceReference::DataView input,
    ::browser::context_hub::mojom::SourceReferencePtr* output) {
  using UnionType = ::browser::context_hub::mojom::SourceReference;
  using Tag = UnionType::Tag;

  switch (input.tag()) {
    case Tag::kGmail: {
      ::context_hub::GmailReference result_gmail{};
      if (!input.ReadGmail(&result_gmail))
        return false;

      *output = UnionType::NewGmail(
          std::move(result_gmail));
      break;
    }
    case Tag::kPhotos: {
      ::browser::context_hub::mojom::PhotosReferencePtr result_photos{};
      if (!input.ReadPhotos(&result_photos))
        return false;

      *output = UnionType::NewPhotos(
          std::move(result_photos));
      break;
    }
    case Tag::kDrive: {
      ::browser::context_hub::mojom::DriveFilePtr result_drive{};
      if (!input.ReadDrive(&result_drive))
        return false;

      *output = UnionType::NewDrive(
          std::move(result_drive));
      break;
    }
    case Tag::kChromeHistoryEntry: {
      ::context_hub::ChromeHistoryEntry result_chrome_history_entry{};
      if (!input.ReadChromeHistoryEntry(&result_chrome_history_entry))
        return false;

      *output = UnionType::NewChromeHistoryEntry(
          std::move(result_chrome_history_entry));
      break;
    }
    default:

      return false;
  }
  return true;
}

