void PageHandlerAsyncWaiter::GenerateFirstPartyAutoTodos(
    bool* out_success) {
  base::RunLoop loop;
  proxy_->GenerateFirstPartyAutoTodos(
      base::BindOnce(
          [](base::RunLoop* loop,
             bool* out_success
,
             bool success) {*out_success = std::move(success);
            loop->Quit();
          },
          &loop,
          out_success));
  loop.Run();
}

bool PageHandlerAsyncWaiter::GenerateFirstPartyAutoTodos(
    ) {
  bool async_wait_result;
  GenerateFirstPartyAutoTodos(&async_wait_result);
  return async_wait_result;
}

void PageHandlerAsyncWaiter::GetAutoTodos(
    std::vector<::context_hub::AutoTodoEntry>* out_first_party_todos, std::vector<::context_hub::AutoTodoEntry>* out_third_party_todos, ::context_hub::AutoTodosGenerationMetadata* out_first_party_metadata, ::context_hub::AutoTodosGenerationMetadata* out_third_party_metadata) {
  base::RunLoop loop;
  proxy_->GetAutoTodos(
      base::BindOnce(
          [](base::RunLoop* loop,
             std::vector<::context_hub::AutoTodoEntry>* out_first_party_todos
,
             std::vector<::context_hub::AutoTodoEntry>* out_third_party_todos
,
             ::context_hub::AutoTodosGenerationMetadata* out_first_party_metadata
,
             ::context_hub::AutoTodosGenerationMetadata* out_third_party_metadata
,
             const std::vector<::context_hub::AutoTodoEntry>& first_party_todos,
             const std::vector<::context_hub::AutoTodoEntry>& third_party_todos,
             const ::context_hub::AutoTodosGenerationMetadata& first_party_metadata,
             const ::context_hub::AutoTodosGenerationMetadata& third_party_metadata) {*out_first_party_todos = std::move(first_party_todos);*out_third_party_todos = std::move(third_party_todos);*out_first_party_metadata = std::move(first_party_metadata);*out_third_party_metadata = std::move(third_party_metadata);
            loop->Quit();
          },
          &loop,
          out_first_party_todos,
          out_third_party_todos,
          out_first_party_metadata,
          out_third_party_metadata));
  loop.Run();
}



